        }

        /// <summary>
        /// Matches files in the specified directory or subdirectories according to the provided glob patterns
        /// and returns them as a lazily evaluated sequence of <see cref="ChainablePath"/> objects.
        /// </summary>
        /// <remarks>
        /// See also <seealso href="https://learn.microsoft.com/en-us/dotnet/core/extensions/file-globbing"/>
        /// <para>
        /// The underlying <see cref="Matcher"/> from Microsoft.Extensions.FileSystemGlobbing walks the entire
        /// directory tree and materializes all matches internally before <c>Execute</c> returns, so this method
        /// does not reduce the amount of file-system work compared to
        /// <see cref="GlobFiles(ChainablePath, string[])"/>. It is offered for API ergonomics only, e.g. to allow
        /// <c>.FirstOrDefault()</c> style chaining without forcing an intermediate array. Because the sequence is
        /// produced lazily on each enumeration, iterating it more than once will re-run the full underlying
